import React from 'react';
import { Box, Typography } from '@mui/material';

export default function MediaMessage({ message }) {
  const url = message.mediaUrl;
  if (message.kind === 'video' && url) {
    return (
      <Box component="video" controls src={url} sx={{ maxWidth: '100%', borderRadius: 1 }} />
    );
  }
  if (message.kind === 'audio' && url) {
    return <Box component="audio" controls src={url} sx={{ width: '100%' }} />;
  }
  if (url) {
    return (
      <Box
        component="img"
        src={url}
        alt=""
        sx={{ maxWidth: '100%', borderRadius: 1, display: 'block' }}
      />
    );
  }
  return (
    <Typography variant="body2">{message.text || 'Media'}</Typography>
  );
}
