import React, { useState } from 'react';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import DriveFileMoveIcon from '@mui/icons-material/DriveFileMove';
import UpdateIcon from '@mui/icons-material/Update';
import SendOutlinedIcon from '@mui/icons-material/SendOutlined';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Typography } from '@mui/material';
import { Button, Dialog } from '../../../../components/ui';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import BulkStatusModal from './BulkStatusModal';
import BulkMoveModal from './BulkMoveModal';

export default function BulkActionsBar({
  selectedCount,
  selectedLeadIds,
  selectedRecordIds,
  workspaceId,
  workspaceName,
  tableId,
  table,
  formItems,
  organisationId,
  canDelete,
  canBulkUpdate,
  canSendTemplate,
  onSendTemplate,
  onClear,
  onSuccess,
  styles,
}) {
  const { showSnackBar } = useSnackBar();
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [statusOpen, setStatusOpen] = useState(false);
  const [moveOpen, setMoveOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!selectedCount) return null;

  const handleBulkDelete = async () => {
    setIsSubmitting(true);
    try {
      const res = await recordService.deleteRecords(selectedLeadIds);
      if (res?.status === 200) {
        showSnackBar(RECORD_COPY.success.deleted, 'success');
        onClear?.();
        onSuccess?.();
        setDeleteOpen(false);
      } else {
        showSnackBar(RECORD_COPY.errors.deleteFailed, 'error');
      }
    } catch {
      showSnackBar(RECORD_COPY.errors.deleteFailed, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <>
      <Box sx={styles?.recordsBulkBarRoot}>
        <Box sx={styles?.recordsBulkBarLeft}>
          <Typography sx={styles?.recordsBulkCount}>
            {RECORD_COPY.bulk.selected(selectedCount)}
          </Typography>
          <Button variant="ghost" size="sm" icon={<CloseIcon />} onClick={onClear}>
            {RECORD_COPY.bulk.clear}
          </Button>
        </Box>

        <Box sx={styles?.recordsBulkBarActions}>
          {canBulkUpdate ? (
            <Button
              variant="outline"
              size="sm"
              icon={<UpdateIcon />}
              onClick={() => setStatusOpen(true)}
            >
              {RECORD_COPY.bulk.updateStatus}
            </Button>
          ) : null}

          {canBulkUpdate ? (
            <Button
              variant="outline"
              size="sm"
              icon={<DriveFileMoveIcon />}
              onClick={() => setMoveOpen(true)}
            >
              {RECORD_COPY.bulk.moveTo}
            </Button>
          ) : null}

          {canSendTemplate ? (
            <Button
              variant="outline"
              size="sm"
              icon={<SendOutlinedIcon />}
              onClick={() => onSendTemplate?.()}
              aria-label={RECORD_COPY.bulk.sendTemplate}
            >
              {RECORD_COPY.bulk.sendTemplate}
            </Button>
          ) : null}

          {canDelete ? (
            <Button
              variant="destructive"
              size="sm"
              icon={<DeleteOutlineIcon />}
              onClick={() => setDeleteOpen(true)}
            >
              {RECORD_COPY.bulk.delete}
            </Button>
          ) : null}
        </Box>
      </Box>

      <Dialog
        open={deleteOpen}
        onClose={() => setDeleteOpen(false)}
        title={RECORD_COPY.deleteConfirm.titleBulk}
        maxWidth="xs"
        actions={
          <>
            <Button variant="ghost" onClick={() => setDeleteOpen(false)}>
              {RECORD_COPY.deleteConfirm.cancel}
            </Button>
            <Button variant="destructive" loading={isSubmitting} onClick={handleBulkDelete}>
              {RECORD_COPY.deleteConfirm.confirm}
            </Button>
          </>
        }
      >
        {RECORD_COPY.deleteConfirm.message}
      </Dialog>

      <BulkStatusModal
        open={statusOpen}
        onClose={() => setStatusOpen(false)}
        tableId={tableId}
        formItems={formItems}
        selectedRecordIds={selectedRecordIds}
        onSuccess={() => {
          onClear?.();
          onSuccess?.();
        }}
      />

      <BulkMoveModal
        open={moveOpen}
        onClose={() => setMoveOpen(false)}
        workspaceId={workspaceId}
        workspaceName={workspaceName}
        table={table}
        formItems={formItems}
        selectedLeadIds={selectedLeadIds}
        organisationId={organisationId}
        onSuccess={() => {
          onClear?.();
          onSuccess?.();
        }}
      />
    </>
  );
}
