import { resolveLeadPhoneFromRow } from '../../utils/leadTemplateSendUtils';

export function resolveWhatsappName(row) {
  const rawLead = row?._rawLead ?? row;
  return (
    rawLead?.whatsapp_name
    || rawLead?.name
    || row?.name
    || rawLead?.lead_id
    || row?.lead_id
    || ''
  );
}

export function buildLeadChatBaseContext(row, organisationId) {
  if (!row) return null;

  const phoneResult = resolveLeadPhoneFromRow(row);
  if (!phoneResult.valid) return null;

  return {
    phoneNumber: phoneResult.normalized,
    organisationId: organisationId || '',
    whatsappName: resolveWhatsappName(row),
    leadId: String(row?.lead_id ?? row?._rawLead?.lead_id ?? ''),
    rowId: String(row?.id ?? row?.lead_id ?? ''),
  };
}

export function buildLeadChatContext(baseContext, botNumber) {
  if (!baseContext || !botNumber) return null;
  return {
    ...baseContext,
    botNumber: String(botNumber),
  };
}

export function getLeadChatKey(phoneNumber, botNumber) {
  if (!phoneNumber || !botNumber) return '';
  return `${phoneNumber}:${botNumber}`;
}
