import { templateService } from '../../../../whatsapp-templates/services/templateService';
import { mapBotToSelectOption } from '../../../../whatsapp-templates/utils/normalizeTemplate';
import { resolveDefaultBotNumber } from '../../utils/leadTemplateSendUtils';
import { normalizeBotListResponse, normalizeMessagesResponse } from '../adapters/leadChatAdapter';
import { leadChatService } from '../services/leadChatService';

export function resolveBotFromForm(formPayload) {
  const bot = resolveDefaultBotNumber(formPayload);
  return bot ? String(bot) : '';
}

export async function fetchOrganisationBots(organisationId) {
  if (!organisationId) return [];
  const res = await templateService.getBotNumbers(organisationId);
  return normalizeBotListResponse(res)
    .map(mapBotToSelectOption)
    .filter(Boolean);
}

function getLatestMessageTimestamp(messages = []) {
  let latest = 0;
  messages.forEach((message) => {
    const raw = message?.created_at || message?.timestamp || message?.updated_at;
    const parsed = raw ? Date.parse(raw) : NaN;
    if (Number.isFinite(parsed) && parsed > latest) {
      latest = parsed;
    }
  });
  return latest;
}

export async function probeBotWithMostHistory({ phoneNumber, organisationId, bots = [] }) {
  if (!phoneNumber || !bots.length) {
    return { botNumber: '', probeResults: [] };
  }

  const probeResults = await Promise.all(
    bots.map(async (bot) => {
      const botNumber = bot?.wa_phone_number || bot?.value || '';
      if (!botNumber) {
        return { botNumber: '', totalCount: 0, latestTs: 0 };
      }

      try {
        const res = await leadChatService.getMessages({
          phone_number: phoneNumber,
          botNumber,
          organisationId,
          page: 1,
          pageLimit: 1,
        });
        const { messages, totalCount } = normalizeMessagesResponse(res);
        return {
          botNumber,
          totalCount,
          latestTs: getLatestMessageTimestamp(messages),
        };
      } catch {
        return { botNumber, totalCount: 0, latestTs: 0 };
      }
    })
  );

  const sorted = [...probeResults].sort((a, b) => {
    if (b.totalCount !== a.totalCount) return b.totalCount - a.totalCount;
    return b.latestTs - a.latestTs;
  });

  return {
    botNumber: sorted[0]?.botNumber || bots[0]?.wa_phone_number || bots[0]?.value || '',
    probeResults,
  };
}

/**
 * Resolve bot for lead chat: form config → org list → probe when multiple.
 */
export async function resolveLeadChatBot({
  formPayload,
  organisationId,
  phoneNumber,
}) {
  const formBot = resolveBotFromForm(formPayload);
  if (formBot) {
    const orgBots = await fetchOrganisationBots(organisationId);
    return {
      botNumber: formBot,
      botOptions: orgBots,
      showSelector: orgBots.length > 1,
      source: 'form',
    };
  }

  const orgBots = await fetchOrganisationBots(organisationId);
  if (!orgBots.length) {
    return {
      botNumber: '',
      botOptions: [],
      showSelector: false,
      source: 'none',
      error: 'noBots',
    };
  }

  if (orgBots.length === 1) {
    return {
      botNumber: orgBots[0].wa_phone_number,
      botOptions: orgBots,
      showSelector: false,
      source: 'org',
    };
  }

  const { botNumber } = await probeBotWithMostHistory({
    phoneNumber,
    organisationId,
    bots: orgBots,
  });

  return {
    botNumber,
    botOptions: orgBots,
    showSelector: true,
    source: 'org-probe',
  };
}
