      sessionBannerAction: leadChat.sessionBannerAction ?? {},
      bubbleMine: leadChat.bubbleMine ?? {},
      bubbleTheirs: leadChat.bubbleTheirs ?? {},
      bubbleMetaMine: leadChat.bubbleMetaMine ?? {},
      bubbleMetaTheirs: leadChat.bubbleMetaTheirs ?? {},
      botSelect: leadChat.botSelect ?? {},
