const MAX_FILE_SIZE_MB = 16;

const ACCEPT_BY_KIND = {
  image: 'image/jpeg,image/png,image/webp',
  video: 'video/mp4,video/3gpp',
  document: '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt',
  audio: 'audio/aac,audio/mp4,audio/mpeg,audio/amr,audio/ogg',
};

export function getAttachmentAccept(kind) {
  return ACCEPT_BY_KIND[kind] || '*/*';
}

export function validateAttachmentFile(file, expectedKind) {
  if (!file) {
    return { valid: false, message: 'No file selected' };
  }

  const sizeMb = file.size / (1024 * 1024);
  if (sizeMb > MAX_FILE_SIZE_MB) {
    return { valid: false, message: `File must be under ${MAX_FILE_SIZE_MB}MB` };
  }

  if (expectedKind === 'image' && !file.type.startsWith('image/')) {
    return { valid: false, message: 'Please select an image file' };
  }

  if (expectedKind === 'video' && !file.type.startsWith('video/')) {
    return { valid: false, message: 'Please select a video file' };
  }

  if (expectedKind === 'audio' && !file.type.startsWith('audio/')) {
    return { valid: false, message: 'Please select an audio file' };
  }

  return { valid: true, message: null };
}

function getUploadMessageType(file) {
  if (!file?.type) return 'file';

  const mime = file.type.toLowerCase();

  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  if (
    mime.includes('pdf') ||
    mime.includes('document') ||
    mime.includes('msword') ||
    mime.includes('spreadsheet') ||
    mime.includes('text/plain')
  ) {
    return 'file';
  }

  return 'file';
}

export function buildSendMessageFormData({ phoneNumber, draftMessage, file }) {
  const formData = new FormData();
  formData.append('phone_number', phoneNumber);

  if (file) {
    const uploadType = getUploadMessageType(file);
    formData.append('file', file);
    formData.append('type', uploadType);

    const caption = (draftMessage || '').trim();
    if (caption && uploadType !== 'audio') {
      formData.append('text', caption);
    }
  } else {
    formData.append('type', 'text');
    formData.append('text', draftMessage || '');
  }

  return formData;
}

export function buildOptimisticMessage({ phoneNumber, botNumber, draftMessage, file }) {
  const localId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const type = file
    ? (file.type.startsWith('image/')
      ? 'IMAGE'
      : file.type.startsWith('video/')
        ? 'VIDEO'
        : file.type.startsWith('audio/')
          ? 'AUDIO'
          : 'DOCUMENT')
    : 'TEXT';

  return {
    id: localId,
    msg_id: localId,
    w_id: localId,
    phone_number: phoneNumber,
    bot_number: botNumber,
    origin: 'OUTBOUND',
    created_at: new Date().toISOString(),
    content: {
      type,
      body: { text: draftMessage || (file ? file.name : '') },
    },
    status: { type: 'sent' },
  };
}
