const TYPE_ALIASES = {
  TEXT: 'text',
  TEMPLATE: 'template',
  IMAGE: 'image',
  VIDEO: 'video',
  AUDIO: 'audio',
  DOCUMENT: 'document',
  FILE: 'document',
  BUTTONS: 'buttons',
  LIST: 'list',
};

function firstText(...values) {
  return values.find((v) => typeof v === 'string' && v.trim()) || '';
}

function normalizeRawType(rawType) {
  if (!rawType || typeof rawType !== 'string') return 'text';
  return TYPE_ALIASES[rawType.toUpperCase()] || rawType.toLowerCase();
}

function normalizeStatus(message) {
  const status = message?.status?.type || message?.status || message?.message_status;
  if (!status) return null;
  if (typeof status === 'string') return status.toLowerCase();
  if (typeof status === 'object') return (status.type || status.status || '').toLowerCase();
  return `${status}`.toLowerCase();
}

export function normalizeLeadChatMessage(message) {
  if (!message) {
    return {
      kind: 'text',
      text: '',
      timestamp: null,
      status: null,
      isMine: false,
      raw: message,
    };
  }

  const rawType =
    message?.content?.type
    || message?.content?.body?.type
    || message?.type
    || 'text';

  const kind = normalizeRawType(rawType);
  const text = firstText(
    message?.content?.body?.text,
    message?.content?.text,
    message?.text,
    message?.message
  );

  const timestamp =
    message?.created_at
    || message?.timestamp
    || message?.updated_at
    || null;

  const origin = `${message?.origin || ''}`.toUpperCase();
  const isMine = origin === 'OUTBOUND';

  return {
    kind,
    text,
    timestamp,
    status: normalizeStatus(message),
    isMine,
    mediaUrl:
      message?.content?.header?.link
      || message?.content?.image?.link
      || message?.content?.video?.link
      || message?.content?.document?.link
      || message?.content?.audio?.link
      || message?.media_url
      || '',
    templateName: message?.template_name || message?.content?.template_name || '',
    raw: message,
  };
}

export function getMessageKey(message, index) {
  const id = message?.msg_id || message?.w_id || message?.id || message?.message_id;
  return id ? String(id) : `idx-${index}`;
}
