export function isLeadChatSessionActive(user) {
  return Boolean(user?.intervene && user?.session_start);
}

export function canShowSessionToggle() {
  return true;
}

export function canStartLeadChatSession(user) {
  if (isLeadChatSessionActive(user)) return false;
  return true;
}

export function canEndLeadChatSession(user) {
  return isLeadChatSessionActive(user);
}

export function buildSessionTogglePayload({ phoneNumber, botNumber, user, start }) {
  return {
    phone_number: phoneNumber,
    bot_number: botNumber,
    intervene: start,
    session_start: start,
    ...(user?.session_id ? { session_id: user.session_id } : {}),
  };
}
