import { useMemo } from 'react';
import useFeatureTheme from '../../../theme/hooks/useFeatureTheme';
import {
  createBusinessFunctionsTableFilters,
  createBusinessFunctionsTableOverrides,
} from '../styles/businessFunctionsTableStyles';

/**
 * Templates-inspired table styling for Business Functions record tables.
 */
export default function useBusinessFunctionsTableSx() {
  const { semantic, chat } = useFeatureTheme();

  return useMemo(
    () => ({
      tableOverrides: createBusinessFunctionsTableOverrides({
        semantic,
        accent: chat,
      }),
      tableFilters: createBusinessFunctionsTableFilters({ semantic }),
    }),
    [semantic, chat]
  );
}
