import React from 'react';
import { Menu, MenuItem } from '@mui/material';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';

export default function LeadChatComposerAttachMenu({
  anchorEl,
  open,
  onClose,
  canSendTemplate = false,
  onPickTemplate,
  onPickImage,
  onPickVideo,
  onPickDocument,
  onPickVoice,
}) {
  return (
    <Menu anchorEl={anchorEl} open={open} onClose={onClose}>
      {canSendTemplate ? (
        <MenuItem
          onClick={() => {
            onClose?.();
            onPickTemplate?.();
          }}
        >
          {LEAD_CHAT_COPY.composer.template}
        </MenuItem>
      ) : null}
      <MenuItem
        onClick={() => {
          onClose?.();
          onPickImage?.();
        }}
      >
        {LEAD_CHAT_COPY.composer.image}
      </MenuItem>
      <MenuItem
        onClick={() => {
          onClose?.();
          onPickVideo?.();
        }}
      >
        {LEAD_CHAT_COPY.composer.video}
      </MenuItem>
      <MenuItem
        onClick={() => {
          onClose?.();
          onPickDocument?.();
        }}
      >
        {LEAD_CHAT_COPY.composer.document}
      </MenuItem>
      <MenuItem
        onClick={() => {
          onClose?.();
          onPickVoice?.();
        }}
      >
        {LEAD_CHAT_COPY.composer.voice}
      </MenuItem>
    </Menu>
  );
}
