import React, { useState } from 'react';
import {
  Avatar,
  Box,
  IconButton,
  Menu,
  MenuItem,
  Tooltip,
  Typography,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import RemoveIcon from '@mui/icons-material/Remove';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import {
  getConversationAvatarInitial,
  getConversationDisplayName,
  formatLastSeenLabel,
} from '../utils/leadChatIdentity';
import {
  canEndLeadChatSession,
  canStartLeadChatSession,
} from '../utils/leadChatSessionRules';
import useLeadChatSx from '../hooks/useLeadChatSx';

export default function LeadChatHeader({
  conversation,
  userDetail,
  onMinimize,
  onClose,
  onToggleSession,
}) {
  const sx = useLeadChatSx();
  const [menuAnchor, setMenuAnchor] = useState(null);
  const displayName = getConversationDisplayName({
    whatsappName: conversation?.whatsappName,
    leadId: conversation?.leadId,
  });
  const initial = getConversationAvatarInitial({ whatsappName: displayName });
  const lastSeen = formatLastSeenLabel(userDetail);
  const canStart = canStartLeadChatSession(userDetail);
  const canEnd = canEndLeadChatSession(userDetail);

  return (
    <Box sx={sx.header}>
      <Avatar sx={sx.headerAvatar}>{initial}</Avatar>
      <Box sx={{ flex: 1, minWidth: 0, ml: 1 }}>
        <Typography sx={sx.headerTitle} noWrap>
          {displayName}
        </Typography>
        <Typography sx={sx.headerSubtitle} noWrap>
          {lastSeen || LEAD_CHAT_COPY.header.statusActive}
        </Typography>
      </Box>
      <Tooltip title={LEAD_CHAT_COPY.header.menu}>
        <IconButton size="small" onClick={(e) => setMenuAnchor(e.currentTarget)}>
          <MoreVertIcon sx={{ fontSize: 18 }} />
        </IconButton>
      </Tooltip>
      <Menu
        anchorEl={menuAnchor}
        open={Boolean(menuAnchor)}
        onClose={() => setMenuAnchor(null)}
        slotProps={{
          paper: { sx: { borderRadius: '8px', minWidth: 180 } },
        }}
      >
        {canStart ? (
          <MenuItem
            onClick={() => {
              setMenuAnchor(null);
              onToggleSession?.();
            }}
          >
            {LEAD_CHAT_COPY.header.startSession}
          </MenuItem>
        ) : null}
        {canEnd ? (
          <MenuItem
            onClick={() => {
              setMenuAnchor(null);
              onToggleSession?.();
            }}
          >
            {LEAD_CHAT_COPY.header.endSession}
          </MenuItem>
        ) : null}
      </Menu>
      <Tooltip title={LEAD_CHAT_COPY.header.minimize}>
        <IconButton size="small" onClick={onMinimize}>
          <RemoveIcon sx={{ fontSize: 18 }} />
        </IconButton>
      </Tooltip>
      <Tooltip title={LEAD_CHAT_COPY.header.close}>
        <IconButton size="small" onClick={onClose}>
          <CloseIcon sx={{ fontSize: 18 }} />
        </IconButton>
      </Tooltip>
    </Box>
  );
}
